import React from 'react';

// This component uses JSX and inline styles to recreate your logo design.
// It's designed to be placed inside a colored, circular container.
const Logo = () => {
  // Style objects to mimic your CSS classes
  const styles = {
    book: {
      width: '50%', height: '40%', backgroundColor: 'white', position: 'relative', zIndex: 2,
    },
    bookSpine: {
      content: '""', position: 'absolute', left: '50%', top: 0, bottom: 0, width: '2px', backgroundColor: '#1e3a5f', transform: 'translateX(-50%)',
    },
    gradCap: {
      position: 'absolute', top: '22%', left: '50%', transform: 'translateX(-50%)', zIndex: 3,
    },
    capTop: {
      width: '35px', height: '4px', backgroundColor: 'white', position: 'relative', margin: '0 auto',
    },
    capMortarboard: {
      content: '""', position: 'absolute', left: 0, top: 0, width: 0, height: 0,
      borderLeft: '17.5px solid transparent', borderRight: '17.5px solid transparent',
      borderBottom: '8px solid white', transform: 'translateY(-8px)',
    },
    capBase: {
      width: '20px', height: '10px', backgroundColor: 'white', margin: '0 auto', marginTop: '-2px',
    },
    orbit: {
      position: 'absolute', borderWidth: '2px', borderColor: 'white', borderRadius: '50%',
      width: '90%', height: '50%', top: '50%', left: '50%',
      transform: 'translate(-50%, -50%) rotate(-10deg)',
    },
    dot: {
      position: 'absolute', backgroundColor: 'white', borderRadius: '50%',
    },
  };

  // Helper to create book lines
  const BookLine = ({ top, left }) => (
    <div style={{ position: 'absolute', height: '2px', backgroundColor: '#1e3a5f', borderRadius: '1px', width: '35%', top, left }} />
  );

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%' }}>
      {/* Orbit and Dots */}
      <div style={styles.orbit}></div>
      <div style={{ ...styles.dot, width: '5px', height: '5px', top: '45%', left: '10%' }}></div>
      <div style={{ ...styles.dot, width: '3px', height: '3px', top: '55%', left: '8%' }}></div>
      <div style={{ ...styles.dot, width: '6px', height: '6px', bottom: '20%', right: '8%' }}></div>

      {/* Graduation Cap */}
      <div style={styles.gradCap}>
        <div style={styles.capTop}>
          <div style={styles.capMortarboard}></div>
        </div>
        <div style={styles.capBase}></div>
      </div>

      {/* Book */}
      <div style={styles.book}>
        <div style={styles.bookSpine}></div>
        {/* Book Lines */}
        <BookLine top="20%" left="10%" /> <BookLine top="20%" left="55%" />
        <BookLine top="40%" left="10%" /> <BookLine top="40%" left="55%" />
        <BookLine top="60%" left="10%" /> <BookLine top="60%" left="55%" />
        <BookLine top="80%" left="10%" /> <BookLine top="80%" left="55%" />
      </div>
    </div>
  );
};

export default Logo;
